from functools import cmp_to_key


def _parse(version):
    """Return (core-tuple, pre-release-list-or-None); build metadata is ignored."""
    without_build = version.split('+', 1)[0]
    if '-' in without_build:
        core, prerelease = without_build.split('-', 1)
        prerelease = prerelease.split('.')
    else:
        core = without_build
        prerelease = None
    return tuple(int(part) for part in core.split('.')), prerelease


def _compare_prerelease_identifier(a, b):
    a_numeric = a.isdigit()
    b_numeric = b.isdigit()

    if a_numeric and b_numeric:
        a_value = int(a)
        b_value = int(b)
        return (a_value > b_value) - (a_value < b_value)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    return (a > b) - (a < b)


def _compare_versions(a, b):
    a_core, a_pre = _parse(a)
    b_core, b_pre = _parse(b)

    if a_core != b_core:
        return (a_core > b_core) - (a_core < b_core)

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for a_id, b_id in zip(a_pre, b_pre):
        result = _compare_prerelease_identifier(a_id, b_id)
        if result:
            return result

    return (len(a_pre) > len(b_pre)) - (len(a_pre) < len(b_pre))


def sort_versions(vs):
    """Sort semantic version strings by SemVer precedence, lowest first."""
    return sorted(vs, key=cmp_to_key(_compare_versions))
